package com.coworkhub.service;
import com.coworkhub.entity.*;import com.coworkhub.repository.BookingRepository;import org.springframework.stereotype.Service;import java.math.*;import java.time.*;import java.util.*;
@Service public class BookingPricingServiceImpl implements BookingPricingService {private final BookingRepository bookings;public BookingPricingServiceImpl(BookingRepository b){bookings=b;}public BigDecimal calculateRoomCost(Member member,Room room,LocalDateTime start,LocalDateTime end){double hours=Duration.between(start,end).toMinutes()/60.0;YearMonth month=YearMonth.from(start);List<Booking> prior=bookings.findByMemberIdAndStartTimeBetween(member.id,month.atDay(1).atStartOfDay(),month.plusMonths(1).atDay(1).atStartOfDay()).stream().filter(x->x.status!=Enums.BookingStatus.CANCELLED).toList();double used=prior.stream().mapToDouble(x->Duration.between(x.startTime,x.endTime).toMinutes()/60.0).sum();double includedLeft=Math.max(0,member.plan.includedHoursPerMonth-used);double excess=Math.max(0,hours-includedLeft);BigDecimal discountFactor=BigDecimal.valueOf(100-member.plan.overageDiscount).divide(BigDecimal.valueOf(100),4,RoundingMode.HALF_UP);return room.hourlyRate.multiply(BigDecimal.valueOf(excess)).multiply(discountFactor).setScale(2,RoundingMode.HALF_UP);}}
